-- Timestamp generated by supabase migration new event_reviews.
-- Adapted from Rizky's feature-1 Review model at commit 51a7264.
-- Additive only: existing identities, rewards and purchase records are preserved.
CREATE TABLE temuevent.reviews (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  event_id UUID NOT NULL,
  user_id UUID NOT NULL,
  rating INTEGER NOT NULL,
  comment TEXT,
  created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT reviews_event_id_fkey FOREIGN KEY (event_id)
    REFERENCES temuevent.events(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT reviews_user_id_fkey FOREIGN KEY (user_id)
    REFERENCES temuevent.users(id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT reviews_event_id_user_id_key UNIQUE (event_id, user_id),
  CONSTRAINT reviews_rating_check CHECK (rating BETWEEN 1 AND 5)
);
CREATE INDEX reviews_event_id_idx ON temuevent.reviews(event_id);
CREATE INDEX reviews_user_id_idx ON temuevent.reviews(user_id);

-- Custom Express sessions authorize authors and attendance. The Data API has no access.
ALTER TABLE temuevent.reviews ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON temuevent.reviews FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT, INSERT ON temuevent.reviews TO temuevent_app;
CREATE POLICY reviews_backend_read ON temuevent.reviews
  FOR SELECT TO temuevent_app USING (true);
CREATE POLICY reviews_backend_insert ON temuevent.reviews
  FOR INSERT TO temuevent_app WITH CHECK (true);
